  assert.equal(totals.voucher, 500);
});

test('invoiceTotals calculates total with voucher', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SUMMER2026', amount: 500 }).value;
  const totals = invoiceTotals(r2);
  assert.equal(totals.total, totals.subtotal + totals.vat - totals.voucher);
});

test('invoiceTotals returns zero voucher for invoice without voucher', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.voucher, 0);
});

test('createInvoice creates an invoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
