import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const r = createInvoice({
    customerId: '  c-001  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice sets default terms to NET30', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice EOM at month end', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-28',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice EOM in February', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-02-28');
});

test('createInvoice rejects invalid terms', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
      terms: 'INVALID',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );
});

test('applyVoucher adds voucher to draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SUMMER2026', amount: 5000 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.voucher.code, 'SUMMER2026');
  assert.equal(r2.value.voucher.amount, 5000);
});

test('applyVoucher rejects non-draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []).value;
  assert.deepEqual(applyVoucher(issued, { code: 'SUMMER2026', amount: 5000 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('applyVoucher rejects duplicate voucher', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SUMMER2026', amount: 5000 }).value;
  assert.deepEqual(applyVoucher(r2, { code: 'ANOTHER', amount: 1000 }), {
    ok: false,
    error: 'VOUCHER_EXISTS',
  });
});

test('applyVoucher rejects invalid amount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(applyVoucher(r.value, { code: 'SUMMER2026', amount: 0 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });
});

test('applyVoucher rejects non-integer amount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(applyVoucher(r.value, { code: 'SUMMER2026', amount: 99.99 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });
});

test('applyVoucher does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = r.value;
  applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 });
  assert.equal(invoice.voucher, undefined);
});

test('invoiceTotals includes voucher amount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SUMMER2026', amount: 500 }).value;
  const totals = invoiceTotals(r2);
  assert.equal(totals.voucher, 500);
});

test('invoiceTotals calculates total with voucher', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SUMMER2026', amount: 500 }).value;
  const totals = invoiceTotals(r2);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

test('invoiceTotals returns zero voucher for invoice without voucher', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.voucher, 0);
});

test('createInvoice creates an invoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Printed flyer A4 (each)');
});

test('createInvoice reports unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10/07/2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects non-existent date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects missing date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 3.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLines = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(JSON.stringify(lines), originalLines);
});

test('createInvoice returns a copy of lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  r.value.lines[0].qty = 999;
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r2.value.lines[0].qty, 5);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal handles quantity of 1', () => {
  const line = { qty: 1, unitPrice: 1500 };
  assert.equal(lineTotal(line), 1500);
});

test('invoiceTotals calculates subtotal from single line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals calculates subtotal from multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
