  const total = 100000;
  const discount = lineDiscount(line);
  const afterDiscount = total - discount;
  const expected = Math.round(afterDiscount * 0.21);
  assert.equal(lineVat(line), expected);
});

test('lineVat calculates VAT on line total after discount', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  const total = 100000;
